import React from 'react';

import clsx from 'clsx';

import { weekDays } from 'src/resources/dates';

import style from './style.module.less';

interface IDayInfoWidgetProps extends React.HTMLAttributes<HTMLDivElement> {
  date: Date;
}

const DayInfoWidget: React.FC<IDayInfoWidgetProps> = ({ date, className, ...rest }) => (
  <span className={clsx('text-muted', style.scheduleDay, className)} {...rest}>
    {date.toLocaleDateString()}
    <hr className="m-0" />
    {weekDays[date.getDay()]}
  </span>
);

export default DayInfoWidget;
